function minDistance(word1: string, word2: string): number {
  const m = word1.length;
  const n = word2.length;

  // dp[i][j] — расстояние между первыми i символами word1 и первыми j символами word2
  const dp: number[][] = Array.from({ length: m + 1 }, () => new Array<number>(n + 1).fill(0));

  // Из префикса длины i в пустую строку — i удалений
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  // Из пустой строки в префикс длины j — j вставок
  for (let j = 0; j <= n; j++) dp[0][j] = j;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (word1[i - 1] === word2[j - 1]) {
        // Последние символы совпали — ничего делать не нужно
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] =
          1 +
          Math.min(
            dp[i - 1][j - 1], // заменить word1[i-1] на word2[j-1]
            dp[i - 1][j], // удалить word1[i-1]
            dp[i][j - 1], // вставить word2[j-1]
          );
      }
    }
  }

  return dp[m][n];
}

// Время: O(m · n)
// Память: O(m · n); можно сжать до O(n), храня две строки таблицы
